function ls_public_host(string $host): bool {
 if(filter_var($host,FILTER_VALIDATE_IP)) return (bool)filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE);
 if($host==='localhost'||str_ends_with($host,'.localhost')||str_ends_with($host,'.local')) return false;
 $records=@dns_get_record($host,DNS_A|DNS_AAAA); if(!$records)return false;
 foreach($records as $r){$ip=$r['ip']??$r['ipv6']??'';if($ip!==''&&!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return false;}return true;
}
function ls_in_scope(string $url,array $domains): bool {$p=parse_url($url);if(!$p||empty($p['host'])||!in_array(strtolower($p['scheme']??''),['http','https'],true)||isset($p['user']))return false;return in_array(strtolower($p['host']),$domains,true)&&ls_public_host(strtolower($p['host']));}
function normalize_target(string $base,string $href): ?array {
 $href=trim(html_entity_decode($href,ENT_QUOTES|ENT_HTML5,'UTF-8'));if($href===''||preg_match('~^(javascript:|mailto:|tel:|data:|blob:)~i',$href))return null;
 $bp=parse_url($base);if(!$bp||empty($bp['scheme'])||empty($bp['host']))return null;$fragment='';if(($q=strpos($href,'#'))!==false){$fragment=substr($href,$q+1);$href=substr($href,0,$q);}if($href==='' )$url=$base;elseif(parse_url($href,PHP_URL_SCHEME))$url=$href;elseif(str_starts_with($href,'//'))$url=$bp['scheme'].':'.$href;else{$origin=$bp['scheme'].'://'.$bp['host'].(isset($bp['port'])?':'.$bp['port']:'');if(str_starts_with($href,'/'))$url=$origin.$href;else{$path=$bp['path']??'/';$dir=substr($path,0,(strrpos($path,'/')===false?0:strrpos($path,'/')+1));$url=$origin.$dir.$href;}}
 $p=parse_url($url);if(!$p||empty($p['host'])||!in_array(strtolower($p['scheme']??''),['http','https'],true)||isset($p['user']))return null;$path=$p['path']??'/';$stack=[];foreach(explode('/',$path) as $seg){$seg=rawurldecode($seg);if($seg===''||$seg==='.')continue;if($seg==='..')array_pop($stack);else $stack[]=rawurlencode($seg);} $clean=strtolower($p['scheme']).'://'.strtolower($p['host']).(isset($p['port'])?':'.$p['port']:'').'/'.implode('/',$stack);if(str_ends_with($path,'/')&&!str_ends_with($clean,'/'))$clean.='/';if(isset($p['query']))$clean.='?'.$p['query'];return ['url'=>substr($clean,0,500),'fragment'=>substr($fragment,0,150),'host'=>strtolower($p['host'])];
}
function ls_failure_category(string $detail): string { if (preg_match('/timed out|timeout/i',$detail)) return 'unknown'; if (preg_match('/getaddrinfo|could not resolve|connection refused|network is unreachable|no route to host|failed to open stream/i',$detail)) return 'connection_error'; return 'unknown'; }
function ls_fetch(string $url,array $domains,float $timeout): array {
 $chain=[];$current=$url;
 for($hop=0;$hop<=5;$hop++){
  if(!ls_in_scope($current,$domains))return ['body'=>'','status'=>0,'final'=>$current,'chain'=>implode(' -> ',$chain),'error'=>'Bỏ qua: URL/đích chuyển hướng nằm ngoài phạm vi an toàn'];
  $ctx=stream_context_create(['http'=>['method'=>'GET','timeout'=>$timeout,'ignore_errors'=>true,'follow_location'=>0,'max_redirects'=>0,'header'=>"User-Agent: LinkScope/2.0 (authorized educational checker)\r\nConnection: close\r\n"],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);
  $warning='';set_error_handler(function($severity,$message)use(&$warning){$warning=(string)$message;return true;});try{$body=file_get_contents($current,false,$ctx);}finally{restore_error_handler();}$headers=$http_response_header??[];$status=0;foreach($headers as $h){if(preg_match('~^HTTP/\S+\s+(\d{3})~i',$h,$m))$status=(int)$m[1];}
  if($status>=300&&$status<400){$loc='';foreach($headers as $h)if(stripos($h,'Location:')===0){$loc=trim(substr($h,9));break;}if($loc==='')return ['body'=>(string)$body,'status'=>$status,'final'=>$current,'chain'=>implode(' -> ',$chain),'error'=>'Redirect không có Location'];$t=normalize_target($current,$loc);if(!$t)return ['body'=>'','status'=>0,'final'=>$current,'chain'=>implode(' -> ',$chain),'error'=>'Đích redirect không hợp lệ'];$chain[]=$current.' ['.$status.']';$current=$t['url'];continue;}
  return ['body'=>$body===false?'':(string)$body,'status'=>$status,'final'=>$current,'chain'=>implode(' -> ',$chain),'error'=>$status===0?($warning!==''?$warning:'Timeout hoặc lỗi kết nối'):($status>=400?'HTTP '.$status:'')];
 }
 return ['body'=>'','status'=>0,'final'=>$current,'chain'=>implode(' -> ',$chain),'error'=>'Vượt quá 5 lần chuyển hướng'];
}
$p=parse_url($start);if($name===''||strlen($start)>500||!filter_var($start,FILTER_VALIDATE_URL)||!$p||!in_array(strtolower($p['scheme']??''),['http','https'],true)||empty($p['host'])||isset($p['user'])){flash('Tên cấu hình hoặc URL bắt đầu không hợp lệ.','danger');redirect('index.php');}
$host=strtolower($p['host']);$raw=trim((string)($scheduledSite['allowed_domains']??($_POST['allowed_domains']??'')));$domains=$raw===''?[$host]:array_values(array_unique(array_map(fn($d)=>strtolower(trim($d)),explode(',',$raw))));foreach($domains as $d)if(!preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))*$/i',$d)){flash('Domain không hợp lệ.','danger');redirect('index.php');}if(!in_array($host,$domains,true)||!ls_in_scope($start,$domains)){flash('URL bắt đầu không thuộc domain cho phép hoặc không phải địa chỉ công khai có thể xác minh.','danger');redirect('index.php');}
$started=date('Y-m-d H:i:s');try{$pdo->beginTransaction();if($scheduledSite){$siteId=(int)$scheduledSite['id'];$domains=array_values(array_unique(array_map(fn($d)=>strtolower(trim($d)),explode(',',(string)$scheduledSite['allowed_domains']))));}else{$st=$pdo->prepare('INSERT INTO sites(name,start_url,allowed_domains,max_pages,max_depth,request_timeout,max_duration,allow_local,created_at) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$name,$start,implode(', ',$domains),$maxPages,$maxDepth,$timeout,$duration,0,$started]);$siteId=(int)$pdo->lastInsertId();}$st=$pdo->prepare("INSERT INTO scan_runs(site_id,started_at,status) VALUES(?,?,'running')");$st->execute([$siteId,$started]);$runId=(int)$pdo->lastInsertId();$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());if(defined('LINKSCOPE_WORKER')&&LINKSCOPE_WORKER===true){echo "Cannot create scan run\n";exit(1);}flash('Không lưu được phiên quét.','danger');redirect('index.php');}
$queue=[[$start,0]];$seenPages=[];$checkedTargets=[];$pages=0;$linksCount=0;$errors=0;$unchecked=0;$startTime=microtime(true);$stop='Đã hoàn tất';$findings=[];
try {
 while($queue&&$pages<$maxPages&&(microtime(true)-$startTime)<$duration){[$url,$depth]=array_shift($queue);if(isset($seenPages[$url]))continue;$seenPages[$url]=true;if(!ls_in_scope($url,$domains))continue;$res=ls_fetch($url,$domains,$timeout);$pages++;$body=$res['body'];$status=$res['status'];$title='';if(preg_match('~<title[^>]*>(.*?)</title>~is',$body,$m))$title=trim(html_entity_decode(strip_tags($m[1]),ENT_QUOTES|ENT_HTML5,'UTF-8'));
  preg_match_all('~\bid\s*=\s*(["\'])(.*?)\1|\bname\s*=\s*(["\'])(.*?)\3~is',$body,$am,PREG_SET_ORDER);$anchors=[];foreach($am as $a){$v=$a[2]!==''?$a[2]:($a[4]??'');$anchors[]=$v;}$st=$pdo->prepare('INSERT INTO pages(run_id,url,depth,http_status,title,anchors_list,crawled_at) VALUES(?,?,?,?,?,?,?)');$st->execute([$runId,$url,$depth,$status?:null,substr($title,0,255),json_encode(array_values(array_unique($anchors)),JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s')]);$pageId=(int)$pdo->lastInsertId();
  if($status===0||$status>=400){$findings[$url]=['url'=>$url,'base'=>$url,'fragment'=>'','type'=>'page','category'=>$status===0?ls_failure_category($res['error']):'http_error','status'=>$status?:null,'chain'=>$res['chain'],'detail'=>$res['error']?:($status?'HTTP '.$status:'Timeout/lỗi kết nối')];}
  if($body===''||$depth >= $maxDepth)continue;
  preg_match_all('~<(a|img|script|link|iframe|source|video|audio|form)\b[^>]*>~is',$body,$tags,PREG_OFFSET_CAPTURE);
  foreach($tags[0] as $i=>$match){$tag=$match[0];$offset=$match[1];$tn=strtolower($tags[1][$i][0]);$attr=in_array($tn,['img','script','iframe','source','video','audio'],true)?'src':($tn==='form'?'action':'href');if(!preg_match('~\b'.preg_quote($attr,'~').'\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))~i',$tag,$m))continue;$rawHref=$m[1]??'';if($rawHref===''&&isset($m[2]))$rawHref=$m[2];if($rawHref===''&&isset($m[3]))$rawHref=$m[3];$t=normalize_target($url,$rawHref);if(!$t)continue;$linksCount++;$type=in_array($tn,['img','script','link','source','video','audio'],true)?($tn==='img'?'image':'resource'):'link';$line=substr_count(substr($body,0,$offset),"\n")+1;$anchorText='';if($tn==='a'&&preg_match('~>(.*?)</a>~is',$tag,$tx))$anchorText=trim(strip_tags($tx[1]));$st=$pdo->prepare('INSERT INTO links(run_id,source_page_id,source_url,raw_href,normalized_url,base_target_url,fragment,resource_type,line_number,tag_snippet,anchor_text) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$runId,$pageId,$url,substr($rawHref,0,500),$t['url'],$t['url'],$t['fragment'],$type,$line,substr($tag,0,300),substr($anchorText,0,255)]);
   if(in_array($t['host'],$domains,true)&&!isset($seenPages[$t['url']])&&$depth+1<=$maxDepth)$queue[]=[$t['url'],$depth+1];
   if(!in_array($t['host'],$domains,true)){if(!isset($findings[$t['url']]))$findings[$t['url']]=['url'=>$t['url'],'base'=>$t['url'],'fragment'=>$t['fragment'],'type'=>$type,'category'=>'unchecked','status'=>null,'chain'=>'','detail'=>'Ngoài domain cho phép: không truy cập'];continue;}
   $key=$t['url'];if(isset($checkedTargets[$key]))continue;$checkedTargets[$key]=true;$tr=ls_fetch($t['url'],$domains,$timeout);$sc=$tr['status'];$cat=(str_starts_with($tr['error'],'Bỏ qua:')?'unchecked':($sc===0?ls_failure_category($tr['error']):($sc>=400?'http_error':(($sc>=300&&$sc<400)?'redirect':'ok'))));$detail=$tr['error']!==''?$tr['error']:($cat==='ok'?'Phản hồi thành công':($cat==='redirect'?'Chuyển hướng HTTP':'HTTP '.$sc));
   if($t['fragment']!==''&&$type==='link'&&$sc>=200&&$sc<300){$ids=[];if(preg_match_all('~\bid\s*=\s*(["\'])(.*?)\1|\bname\s*=\s*(["\'])(.*?)\3~is',$tr['body'],$idms,PREG_SET_ORDER))foreach($idms as $idrow)$ids[]=$idrow[2]!==''?$idrow[2]:($idrow[4]??'');if(!in_array(rawurldecode($t['fragment']),$ids,true)){$cat='missing_anchor';$detail='Không tìm thấy anchor #'.$t['fragment'];}}
   $findings[$key]=['url'=>$tr['final']?:$t['url'],'base'=>$t['url'],'fragment'=>$t['fragment'],'type'=>$type,'category'=>$cat,'status'=>$sc?:null,'chain'=>$tr['chain'],'detail'=>$detail];
  }
 }
 if($queue&&$pages>=$maxPages)$stop='Đạt giới hạn số trang';elseif($queue)$stop='Đạt giới hạn thời gian';
 foreach($findings as $f){$st=$pdo->prepare('INSERT INTO findings(run_id,normalized_url,base_target_url,fragment,resource_type,status_category,http_status,redirect_chain,error_detail,checked_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([$runId,substr($f['url'],0,500),substr($f['base'],0,500),$f['fragment'],$f['type'],$f['category'],$f['status'],$f['chain'],substr($f['detail'],0,500),date('Y-m-d H:i:s')]);}
 $errors=count(array_filter($findings,fn($f)=>in_array($f['category'],['http_error','connection_error','missing_anchor'],true)));$unchecked=count(array_filter($findings,fn($f)=>in_array($f['category'],['unknown','unchecked'],true)));$st=$pdo->prepare("UPDATE scan_runs SET finished_at=?,status='completed',stop_reason=?,total_pages_crawled=?,total_links_found=?,total_errors=?,total_unchecked=? WHERE id=?");$st->execute([date('Y-m-d H:i:s'),$stop,$pages,$linksCount,$errors,$unchecked,$runId]);if($errors>0){$st=$pdo->prepare('INSERT INTO notifications(run_id,message) VALUES(?,?)');$st->execute([$runId,"Phiên #$runId phát hiện $errors lỗi cần xem lại."]);}if(defined('LINKSCOPE_WORKER')&&LINKSCOPE_WORKER===true){echo "Completed scan #$runId: $pages pages, $linksCount links, $errors errors\n";exit(0);}flash("Quét xong: $pages trang, $linksCount liên kết, $errors lỗi, $unchecked mục chưa xác định/bỏ qua. $stop");redirect('report.php?run_id='.$runId);
}catch(Throwable $e){error_log('LinkScope scan '.$runId.': '.$e->getMessage());$st=$pdo->prepare("UPDATE scan_runs SET finished_at=?,status='failed',stop_reason=? WHERE id=?");$st->execute([date('Y-m-d H:i:s'),'Có lỗi khi xử lý phiên quét',$runId]);if(defined('LINKSCOPE_WORKER')&&LINKSCOPE_WORKER===true){echo "Failed scan #$runId\n";exit(1);}flash('Phiên quét gặp lỗi. Kiểm tra log PHP và cấu trúc database.','danger');redirect('report.php?run_id='.$runId);}
